import{_ as a,o as s,c as i,a0 as t}from"./chunks/framework.C3yZ6M33.js";const k=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/getting-started.md","filePath":"tutorials/getting-started.md"}'),n={name:"tutorials/getting-started.md"};function h(r,e,o,l,d,p){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>This tutorial takes you from zero to a running peregrin node plus the hub that aggregates it. You will need Rust (<code>cargo</code>) and <a href="https://9aia.com/sepia/" target="_blank" rel="noreferrer">sepia</a> installed — peregrin drives the session plane through <code>sepia serve</code>.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p>The <code>peregrin</code> command ships as a tamias pack (<code>libraries/peregrin</code>) — there is no cargo bin to <code>cargo install</code>. With <code>tamias</code> installed:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 9aia:peregrin@0.1.0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # org registry (needs TAMIAS_REGISTRY_TOKEN)</span></span></code></pre></div><p>That deploys the <code>peregrin</code> shim plus the <code>peregrin-node</code>/ <code>peregrin-hub</code> payload bins. From a checkout:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xtask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pack</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                        # stage release bins</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> crates/peregrin-hub</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # the hub daemon</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --allow-drivers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./libraries/peregrin</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # the peregrin command</span></span></code></pre></div><p>Or inside a checkout, <code>cargo xtask install</code> builds <code>peregrin-hub</code> and <code>tamias-driver-peregrin</code> into <code>~/.local</code> — pair it with <code>cargo xtask pack</code> + the <code>tamias install</code> above for the <code>peregrin</code> command itself.</p><h2 id="run-the-node" tabindex="-1">Run the node <a class="header-anchor" href="#run-the-node" aria-label="Permalink to &quot;Run the node&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">peregrin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span></code></pre></div><p>The node binds <code>127.0.0.1:18787</code> by default, discovers sepia drivers on this machine, and serves the <code>/api/*</code> surface — the session routes plus the generic entity plane (<code>/api/entities*</code>, <code>/api/events</code>, <code>/api/node</code>, <code>/api/pair</code>, …) — with an SSE event feed. In another terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">peregrin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">peregrin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sessions</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p>You should see the node&#39;s health row and a merged session list from every agent store sepia can see.</p><h2 id="run-the-hub" tabindex="-1">Run the hub <a class="header-anchor" href="#run-the-hub" aria-label="Permalink to &quot;Run the hub&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PEREGRIN_NODES</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;local=http://127.0.0.1:18787&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">peregrin-hub</span></span></code></pre></div><p>The hub is a headless gateway (default <code>127.0.0.1:13000</code>) — it merges every configured node&#39;s entities and session views into one API and dispatches work across the fleet. There is no bundled web UI on <code>main</code>; the experimental Leptos UI lives on the <code>experimental/web</code> branch. Clients authenticate with <code>PEREGRIN_HUB_TOKEN</code> (loopback is open) and <code>/api/pair</code> trades a one-time code for a bearer credential.</p><h2 id="where-next" tabindex="-1">Where next <a class="header-anchor" href="#where-next" aria-label="Permalink to &quot;Where next&quot;">​</a></h2><ul><li><a href="./first-gate.html">Your first gate</a> — install a bundle through tamias, deploy a campaign node, register the webhook, watch pushes become commit statuses.</li><li><a href="./../explanation/architecture.html">Architecture</a> — how nodes, hub, and the sepia boundary fit together.</li><li><a href="./../how-to/run-a-node.html">Run a node</a> — tokens, non-loopback binds, tamias service units.</li><li><a href="./../reference/environment.html">Environment reference</a> — every <code>PEREGRIN_*</code> knob.</li></ul>`,18)])])}const g=a(n,[["render",h]]);export{k as __pageData,g as default};
